export const escapeHtml = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function authorText(a){return `${a.family} ${a.given.split(/[\s.-]+/).filter(Boolean).map(s=>s[0]).join('')}`}
export function publicationHtml(p){return `<article class="publication" id="${p.id}"><span class="pub-type">${escapeHtml(p.type)} · ${p.year}</span><h3><a href="${escapeHtml(p.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(p.title)}</a></h3><p class="authors">${p.authors.map(a=>a.family.toLowerCase()==='alvi'?`<strong>${escapeHtml(authorText(a))}</strong>`:escapeHtml(authorText(a))).join(', ')}.</p><p class="citation"><i>${escapeHtml(p.journal)}</i>. ${p.year};${escapeHtml(p.volume)}${p.issue?`(${escapeHtml(p.issue)})`:''}${p.pages?`:${escapeHtml(p.pages)}`:''}.</p><a class="doi" href="${escapeHtml(p.url)}" target="_blank" rel="noopener noreferrer">doi: ${escapeHtml(p.doi)}</a></article>`}
export function experienceHtml(e,pubs,interactive=true){return `<section><h3>${escapeHtml(e.institution)}</h3><p class="meta">Research intern · ${escapeHtml(e.dates)}<br> ${escapeHtml(e.department)}</p><ul>${e.details.map(s=>`<li>${escapeHtml(s)}</li>`).join('')}</ul>${e.outcomes?`<h3>Scholarly work</h3>${e.outcomes.map(([status,t])=>`<p><strong>${status}.</strong> ${escapeHtml(t)}</p>`).join('')}`:''}${e.publications.length?`<h3>Related publications</h3><ul>${e.publications.map(id=>{const p=pubs.find(p=>p.id===id);return `<li>${interactive?`<button class="inline-button" data-publication="${id}">${escapeHtml(p.title)}</button>`:`<a href="#${id}">${escapeHtml(p.title)}</a>`}</li>`}).join('')}</ul>`:''}</section>`}
export function servicesHtml(expandable=true){return services.map(s=>expandable?`<details class="service-item"><summary>${escapeHtml(s.name)}</summary><p class="meta">${escapeHtml(s.role)} · ${escapeHtml(s.dates)}</p><p>${escapeHtml(s.description)}</p></details>`:`<section class="service-item"><h3>${escapeHtml(s.name)}</h3><p class="meta">${escapeHtml(s.role)} · ${escapeHtml(s.dates)}</p><p>${escapeHtml(s.description)}</p></section>`).join('')}
export const educationHtml=`<div class="education"><div><h3>Meharry Medical College</h3><p>Doctor of Medicine<br> Class of 2027</p></div><div><h3>New York Institute of Technology</h3><p>BS in Biology<br> August 2022</p></div></div>`;
export function cvHtml(pubs){return `<div class="cv-name"><h3>Zain Alvi</h3><p>MD candidate, Meharry Medical College</p><p><a href="mailto:zainalvi2001@gmail.com">zainalvi2001@gmail.com</a></p></div><section><h3>Education</h3>${educationHtml}</section><section><h3>Research & experience</h3>${experiences.map(e=>experienceHtml(e,pubs,false)).join('')}</section><section><h3>Publications & abstracts</h3>${pubs.map(publicationHtml).join('')}</section><section><h3>Leadership & community service</h3>${servicesHtml(false)}</section><section><h3>Languages</h3><p>Native or bilingual proficiency in English, Urdu, and Sindhi.</p></section>`}
